			"publishable": false,
			"runtime": "neutral",
			"exports": [".", "./mutations"],
			"dependencies": ["hevy-client", "operations"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/hevy-client": ["", "types", "schemas"],
					"@hevy-mcp/operations": [""]
				},
				"forbidden": [
					"@cloudflare/",
					"cloudflare:",
