			"role": "server"
		},
		{
			"id": "worker",
			"path": "packages/worker",
			"name": "@hevy-mcp/worker",
			"private": true,
			"publishable": false,
			"runtime": "workerd",
			"exports": ["."],
			"dependencies": ["hevy-client", "core"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/core": [""],
					"@hevy-mcp/hevy-client": [""]
				},
				"forbidden": ["@sentry/", "@opentelemetry/"],
				"rejectBuiltins": true,
				"rejectDynamicImports": false
			},
			"artifacts": ["worker-bundle"],
			"role": "adapter"
		},
		{
			"id": "cli",
			"path": "packages/cli",
			"name": "@chrisdoc/hevy-cli",
			"private": false,
			"publishable": true,
			"runtime": "node",
			"exports": [],
