		)?.[1];
		expect(encodedRequest).toBeTruthy();

		// 3. The user submits their Hevy API key.
		const approval = await handler(
			new Request("https://worker.example/authorize", {
				method: "POST",
				headers: { origin: "https://worker.example" },
