/// <reference types="@cloudflare/vitest-pool-workers/types" />

import { SELF } from "cloudflare:test";
import { describe, expect, it } from "vitest";

describe("Cloudflare Worker integration", () => {
	it("serves OAuth discovery metadata from the configured Worker", async () => {
		const response = await SELF.fetch(
			"https://worker.example/.well-known/oauth-authorization-server",
		);

		expect(response.status).toBe(200);
		expect(await response.json()).toMatchObject({
			authorization_endpoint: "https://worker.example/authorize",
			token_endpoint: "https://worker.example/token",
			registration_endpoint: "https://worker.example/register",
			scopes_supported: ["mcp"],
			client_id_metadata_document_supported: true,
		});
	});

	it("returns an OAuth challenge for an unauthenticated MCP request", async () => {
		const response = await SELF.fetch("https://worker.example/mcp", {
			method: "POST",
			body: "{}",
		});

		expect(response.status).toBe(401);
		expect(response.headers.get("www-authenticate")).toContain(
			'resource_metadata="https://worker.example/.well-known/oauth-protected-resource/mcp"',
		);
	});
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { HevyHttpError, type HevyClient } from "@hevy-mcp/hevy-client";
import {
	cacheValidation,
	hasCachedValidation,
	MEMORY_CACHE_MAX_ENTRIES,
	resetMemoryValidationCacheForTests,
	validateHevyApiKeyResilient,
	VALIDATION_CACHE_TTL_SECONDS,
	type HevyKeyValidator,
} from "./validation-cache.js";

function createFakeKv() {
	const store = new Map<string, string>();
	return {
		store,
		get: vi.fn((key: string) => Promise.resolve(store.get(key) ?? null)),
		put: vi.fn(
			(key: string, value: string, _options?: { expirationTtl?: number }) => {
				store.set(key, value);
				return Promise.resolve();
			},
		),
		delete: vi.fn((key: string) => {
			store.delete(key);
			return Promise.resolve();
		}),
		list: vi.fn(() => Promise.resolve({ keys: [], list_complete: true })),
	};
}

afterEach(() => {
	resetMemoryValidationCacheForTests();
});

describe("in-memory fallback (no reachable KV binding)", () => {
	it("reports a miss for a key that was never cached", async () => {
		await expect(hasCachedValidation("never-cached", {})).resolves.toBe(false);
	});

	it("reports a hit after caching, scoped to that exact key", async () => {
		await cacheValidation("cached-key", {});

		await expect(hasCachedValidation("cached-key", {})).resolves.toBe(true);
		await expect(hasCachedValidation("other-key", {})).resolves.toBe(false);
	});

	it("expires the cached verdict after the TTL", async () => {
		vi.useFakeTimers();
		try {
			await cacheValidation("expiring-key", {});
			await expect(hasCachedValidation("expiring-key", {})).resolves.toBe(true);

			vi.advanceTimersByTime(VALIDATION_CACHE_TTL_SECONDS * 1_000 + 1);

			await expect(hasCachedValidation("expiring-key", {})).resolves.toBe(
				false,
			);
		} finally {
			vi.useRealTimers();
		}
	});

	it("falls back to memory when OAUTH_KV is not KV-namespace-shaped", async () => {
		const env = { OAUTH_KV: "not-a-kv-namespace" };
		await cacheValidation("legacy-key", env);
		await expect(hasCachedValidation("legacy-key", env)).resolves.toBe(true);
	});

	it("evicts the oldest entry once the cap is exceeded", async () => {
		const env = {};
		for (let index = 0; index < MEMORY_CACHE_MAX_ENTRIES + 1; index++) {
			await cacheValidation(`key-${index}`, env);
		}
		await expect(hasCachedValidation("key-0", env)).resolves.toBe(false);
		await expect(
			hasCachedValidation(`key-${MEMORY_CACHE_MAX_ENTRIES}`, env),
		).resolves.toBe(true);
	});
});

describe("KV-backed cache", () => {
	it("stores a successful validation with the TTL and reads it back", async () => {
		const kv = createFakeKv();
		const env = { OAUTH_KV: kv };

		await cacheValidation("hevy-api-key", env);

		expect(kv.put).toHaveBeenCalledTimes(1);
		const [key, value, options] = kv.put.mock.calls[0] as [
			string,
			string,
			{ expirationTtl?: number },
		];
		expect(key.startsWith("keyvalid:")).toBe(true);
		expect(value).not.toContain("hevy-api-key");
		expect(options?.expirationTtl).toBe(VALIDATION_CACHE_TTL_SECONDS);

		await expect(hasCachedValidation("hevy-api-key", env)).resolves.toBe(true);
		await expect(hasCachedValidation("other-api-key", env)).resolves.toBe(
			false,
		);
	});

	it("derives the same cache key for the same API key, and different keys for different values", async () => {
		const kv = createFakeKv();
		const env = { OAUTH_KV: kv };

		await cacheValidation("key-a", env);
		await cacheValidation("key-a", env);
		await cacheValidation("key-b", env);

		const keys = kv.put.mock.calls.map((call) => call[0] as string);
		expect(keys[0]).toBe(keys[1]);
		expect(keys[0]).not.toBe(keys[2]);
	});

	it("treats a KV read failure as a cache miss rather than throwing", async () => {
		const kv = createFakeKv();
		kv.get.mockRejectedValueOnce(new Error("KV unavailable"));
		const env = { OAUTH_KV: kv };

		await expect(hasCachedValidation("some-key", env)).resolves.toBe(false);
	});

	it("treats a KV write failure as a no-op rather than throwing", async () => {
		const kv = createFakeKv();
		kv.put.mockRejectedValueOnce(new Error("KV unavailable"));
		const env = { OAUTH_KV: kv };

		await expect(cacheValidation("some-key", env)).resolves.toBeUndefined();
	});

	it("does not treat an arbitrary stored value as a valid verdict", async () => {
		const kv = createFakeKv();
		const env = { OAUTH_KV: kv };
		await cacheValidation("tampered-key", env);
		const [key] = kv.put.mock.calls[0] as [
			string,
			string,
			{ expirationTtl?: number },
		];
		kv.store.set(key, "something-else");

		await expect(hasCachedValidation("tampered-key", env)).resolves.toBe(false);
	});
});

describe("validateHevyApiKeyResilient", () => {
	const createValidationClient = () => ({}) as HevyClient;

	function rejectingValidator(status: number, count: number): HevyKeyValidator {
		let calls = 0;
		return vi.fn<HevyKeyValidator>(() => {
			calls += 1;
			if (calls <= count) {
				return Promise.reject(
					new HevyHttpError(`HTTP ${status}`, {
						status,
						method: "GET",
						endpoint: "/v1/user/info",
					}),
				);
			}
			return Promise.resolve("valid");
		});
	}

	it("skips validate entirely on a cache hit", async () => {
		const env = {};
		await cacheValidation("resilient-cached-key", env);
		const validate: HevyKeyValidator = vi.fn();

		const result = await validateHevyApiKeyResilient(
			"resilient-cached-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("valid");
		expect(validate).not.toHaveBeenCalled();
	});

	it("validates and caches on a miss", async () => {
		const env = {};
		const validate: HevyKeyValidator = vi.fn().mockResolvedValue("valid");

		const result = await validateHevyApiKeyResilient(
			"resilient-fresh-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("valid");
		expect(validate).toHaveBeenCalledTimes(1);
		await expect(hasCachedValidation("resilient-fresh-key", env)).resolves.toBe(
			true,
		);
	});

	it("never caches an invalid verdict", async () => {
		const env = {};
		const validate: HevyKeyValidator = vi.fn().mockResolvedValue("invalid");

		const result = await validateHevyApiKeyResilient(
			"resilient-invalid-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("invalid");
		await expect(
			hasCachedValidation("resilient-invalid-key", env),
		).resolves.toBe(false);
	});

	it("retries a transient (non-429) failure and returns the eventual success", async () => {
		const env = {};
		const validate = rejectingValidator(503, 1);

		const result = await validateHevyApiKeyResilient(
			"resilient-retry-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("valid");
		expect(validate).toHaveBeenCalledTimes(2);
	});

	it("never retries a 429", async () => {
		const env = {};
		const error = new HevyHttpError("HTTP 429", {
			status: 429,
			method: "GET",
			endpoint: "/v1/user/info",
		});
		const validate: HevyKeyValidator = vi.fn().mockRejectedValue(error);

		await expect(
			validateHevyApiKeyResilient(
				"resilient-429-key",
				"https://api.hevyapp.com",
				createValidationClient,
				validate,
				env,
			),
		).rejects.toBe(error);
		expect(validate).toHaveBeenCalledTimes(1);
	});

	it("stops retrying when aborted during backoff, without another attempt", async () => {
		const env = {};
		const controller = new AbortController();
		const validate = rejectingValidator(503, 1);

		const pending = validateHevyApiKeyResilient(
			"resilient-abort-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
			{ signal: controller.signal },
		);
		// Abort while the wrapper is sleeping between attempt 1 and attempt 2.
		setTimeout(() => controller.abort(), 10);

		await expect(pending).rejects.toBeInstanceOf(HevyHttpError);
		expect(validate).toHaveBeenCalledTimes(1);
	});

	it("defers the cache write via waitUntil when given an execution context", async () => {
		const env = {};
		const validate: HevyKeyValidator = vi.fn().mockResolvedValue("valid");
		const waitUntil = vi.fn();

		const result = await validateHevyApiKeyResilient(
			"resilient-deferred-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
			undefined,
			{ waitUntil },
		);

		expect(result).toBe("valid");
		expect(waitUntil).toHaveBeenCalledTimes(1);
	});
});

import { existsSync } from "node:fs";
import { readdir, readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import {
	loadArtifactProvenance,
	loadTopology,
	repositoryRoot,
	workspaceById,
} from "./repository-control-plane.mjs";
import { isString } from "./runtime-value-predicates.mjs";

function assert(condition, message) {
	if (!condition) throw new Error(message);
}

function uniqueProvenanceEntry(provenance, collection, id) {
	const entries = provenance?.[collection];
	assert(
		Array.isArray(entries),
		`Artifact provenance ${collection} entries are required`,
	);
	const matches = entries.filter((entry) => entry?.id === id);
	assert(
		matches.length === 1,
		`Artifact provenance ${collection} entry ${id} must be unique`,
	);
	const [entry] = matches;
	assert(
		Array.isArray(entry.paths) && entry.paths.length === 1,
		`Artifact provenance ${collection} entry ${id} must own exactly one path`,
	);
	const [path] = entry.paths;
	assert(
		isString(path) && path.length > 0,
		`Artifact provenance ${collection} entry ${id} path must be non-empty`,
	);
	return path;
}

function uniqueWorkspace(topology, id) {
	assert(
		Array.isArray(topology?.workspaces),
		"Repository topology workspaces are required",
	);
	const matches = topology.workspaces.filter(
		(workspace) => workspace?.id === id,
	);
	assert(
		matches.length === 1,
		`Workspace ${id} must be unique in repository topology`,
	);
	return workspaceById(topology, id);
}

function resolveOutputDirectory(provenance, rootDir) {
	const path = uniqueProvenanceEntry(provenance, "outputs", "worker-dry-run");
	assert(
		/\/\*\*?$/.test(path),
		"Worker dry-run provenance must describe a directory glob",
	);
	return resolve(rootDir, path.replace(/\/\*\*?$/, ""));
}

async function scan(path, unresolvedPrivateImports, failures) {
	const entries = await readdir(path, { withFileTypes: true });
	for (const entry of entries) {
		const target = resolve(path, entry.name);
		if (entry.isDirectory())
			await scan(target, unresolvedPrivateImports, failures);
		else if (/\.(?:js|mjs|cjs)$/.test(entry.name)) {
			const source = await readFile(target, "utf8");
			if (unresolvedPrivateImports.some((name) => source.includes(name))) {
				failures.push(target);
			}
		}
	}
}

export async function checkWorkerBundle({ rootDir = repositoryRoot } = {}) {
	const provenance = loadArtifactProvenance(rootDir);
	const topology = loadTopology(rootDir);
	const worker = uniqueWorkspace(topology, "worker");
	assert(
		Array.isArray(worker.dependencies),
		"Worker workspace dependencies are required",
	);
	const unresolvedPrivateImports = worker.dependencies.map((dependency) => {
		const workspace = uniqueWorkspace(topology, dependency);
		assert(
			workspace.private === true,
			`Worker dependency ${dependency} must be a private workspace`,
		);
		assert(
			isString(workspace.name) && workspace.name.length > 0,
			`Worker dependency ${dependency} package name is required`,
		);
		return workspace.name;
	});
	const outputDir = resolveOutputDirectory(provenance, rootDir);
	if (!existsSync(outputDir)) {
		throw new Error(
			`Worker bundle output directory does not exist: ${outputDir}. ` +
				"Run the worker bundle build step first (e.g., npm run worker:dry-run).",
		);
	}
	const failures = [];
	await scan(outputDir, unresolvedPrivateImports, failures);
	return { failures, outputDir, unresolvedPrivateImports };
}

const isCli =
	process.argv[1] !== undefined &&
	import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isCli) {
	try {
		const result = await checkWorkerBundle();
		if (result.failures.length > 0) {
			console.error(
				`Worker bundle contains private workspace imports:\n${result.failures.join("\n")}`,
			);
			process.exitCode = 1;
		} else {
			console.log(
				"Worker bundle contains no unresolved private workspace imports.",
			);
		}
	} catch (error) {
		console.error(`check-worker-bundle: ${error.message}`);
		process.exitCode = 1;
	}
}

import { readFile } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import {
	loadTopology,
	releaseConsumers,
	workspaceById,
	workspaceByName,
} from "./repository-control-plane.mjs";
import { isString } from "./runtime-value-predicates.mjs";

const execFileAsync = promisify(execFile);
const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");

/**
 * Evaluate package-changeset coverage for a set of changed files.
 *
 * Pure repository logic: every input (which files changed, how changeset
 * files changed, and the base-revision manifest fallback) arrives as a
 * parameter so tests can drive it with ordinary filesystem fixtures without
 * invoking Git. The CLI wrapper gathers those inputs from Git.
 *
 * Returns `{ changedPackageCount }` on success and throws an Error with a
 * human-readable message when coverage is incomplete.
 */
export async function packageChangesetCoverage({
	root,
	changedFiles,
	readManifestFromBase,
	changesetDiffLines,
}) {
	const topology = loadTopology(root);
	const releaseTriggerFiles = new Map(
		topology.release.triggers.map((trigger) => [
			trigger.path,
			workspaceById(topology, trigger.workspace).name,
		]),
	);
	const releaseBumps = new Set(["patch", "minor", "major"]);

	async function readPackageName(packagePath) {
		const manifestPath = `${packagePath}/package.json`;
		const contents = await readFile(resolve(root, manifestPath), "utf8").catch(
			() => readManifestFromBase(packagePath),
		);
		if (contents === undefined) return undefined;

		try {
			const packageJson = JSON.parse(contents);
			return isString(packageJson.name) ? packageJson.name : undefined;
		} catch {
			return undefined;
		}
	}

	const changedPackagePaths = new Set();
	for (const file of changedFiles) {
		const match = file.match(/^packages\/([^/]+)(?:\/|$)/);
		if (match) changedPackagePaths.add(`packages/${match[1]}`);
	}

	const changedPackages = new Map();
	for (const path of changedPackagePaths) {
		const packageName = await readPackageName(path);
		if (packageName) changedPackages.set(path, packageName);
	}
	for (const file of changedFiles) {
		const packageName = releaseTriggerFiles.get(file);
		if (packageName) changedPackages.set(file, packageName);
	}

	if (changedPackages.size === 0) {
		console.log("No workspace package changes require a package changeset.");
		return { changedPackageCount: 0 };
	}

	const changedChangesetFiles = changesetDiffLines
		.flatMap((line) => {
			const [status, sourcePath, destinationPath] = line.split("\t");
			if (status === "A" || status === "M") return [sourcePath];
			if (status.startsWith("R") && status !== "R100") {
				return [destinationPath];
			}
			return [];
		})
		.filter((file) => /^\.changeset\/[^/]+\.md$/.test(file));

	const changesetReleases = new Set();
	const emptyChangesetFiles = [];
	let changedChangesetCount = 0;
	for (const file of changedChangesetFiles) {
		const contents = await readFile(resolve(root, file), "utf8").catch(
			() => undefined,
		);
		if (contents === undefined) continue;
		changedChangesetCount += 1;
		const fileReleases = new Set();
		const frontmatter = contents.match(/^---\s*\n([\s\S]*?)\n---/);
		if (frontmatter) {
			for (const line of frontmatter[1].split("\n")) {
				const match = line.match(
					/^\s*(?:"([^"]+)"|'([^']+)'|([@A-Za-z0-9._/-]+))\s*:\s*([A-Za-z]+)\s*$/,
				);
				if (!match) continue;
				const packageName = match[1] ?? match[2] ?? match[3];
				const bump = match[4];
				if (!releaseBumps.has(bump)) continue;
				fileReleases.add(packageName);
				changesetReleases.add(packageName);
			}
		}
		if (fileReleases.size === 0) emptyChangesetFiles.push(file);
	}

	if (changedChangesetCount === 0) {
		throw new Error(
			`Changed workspace packages need a changeset added or modified by this branch:\n${Array.from(changedPackages.entries(), ([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
		);
	}

	if (emptyChangesetFiles.length > 0) {
		throw new Error(
			`Empty Changesets cannot accompany release-triggering changes:\n${emptyChangesetFiles.map((file) => `- ${file}`).join("\n")}\nRelease-triggering changes require non-empty bumps:\n${Array.from(changedPackages.entries(), ([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
		);
	}

	const missing = [...changedPackages.entries()]
		.filter(([, packageName]) => !changesetReleases.has(packageName))
		.map(([path, packageName]) => `${path} -> ${packageName}`);

	if (missing.length > 0) {
		throw new Error(
			`Changed workspace packages need a changeset naming the same package:\n${missing.map((entry) => `- ${entry}`).join("\n")}`,
		);
	}

	function getTransitiveConsumers(packageName) {
		let workspace = null;
		try {
			workspace = workspaceByName(topology, packageName);
		} catch {
			return [];
		}
		return releaseConsumers(topology, workspace.id).map(
			(consumer) => workspaceById(topology, consumer).name,
		);
	}

	const cascadeRoots = topology.release.bundles.map(
		(bundle) => workspaceById(topology, bundle.workspace).name,
	);
	const incompleteCascades = cascadeRoots
		.filter((packageName) => changesetReleases.has(packageName))
		.map((packageName) => ({
			packageName,
			missing: getTransitiveConsumers(packageName).filter(
				(consumer) => !changesetReleases.has(consumer),
			),
		}))
		.filter(({ missing: missingConsumers }) => missingConsumers.length > 0);

	if (incompleteCascades.length > 0) {
		throw new Error(
			`Bundled release cascades must include every transitive shipped consumer with at least a patch bump:\n${incompleteCascades
				.map(
					({ packageName, missing: missingConsumers }) =>
						`- ${packageName} -> missing ${missingConsumers.join(", ")}`,
				)
				.join("\n")}`,
		);
	}

	const allowedReleases = new Set();
	for (const packageName of changedPackages.values()) {
		allowedReleases.add(packageName);
		for (const consumer of getTransitiveConsumers(packageName)) {
			allowedReleases.add(consumer);
		}
	}
	const unrelatedReleases = [...changesetReleases].filter(
		(packageName) => !allowedReleases.has(packageName),
	);
	if (unrelatedReleases.length > 0) {
		throw new Error(
			`Changesets must not couple unrelated package releases:\n${unrelatedReleases
				.map((packageName) => `- ${packageName}`)
				.join("\n")}`,
		);
	}

	console.log(
		`Package changeset coverage passed for ${changedPackages.size} workspace package(s).`,
	);
	return { changedPackageCount: changedPackages.size };
}

const isMain =
	process.argv[1] !== undefined &&
	import.meta.url === pathToFileURL(process.argv[1]).href;

if (isMain) {
	const sinceIndex = process.argv.indexOf("--since");
	const since = sinceIndex >= 0 ? process.argv[sinceIndex + 1] : "origin/main";

	if (!since) throw new Error("Missing value for --since");

	const { stdout } = await execFileAsync(
		"git",
		["diff", "--name-only", "--diff-filter=ACMRD", `${since}...HEAD`],
		{ cwd: repositoryRoot },
	);
	const changedFiles = stdout.trim().split("\n").filter(Boolean);
	const readManifestFromBase = async (packagePath) => {
		try {
			const result = await execFileAsync(
				"git",
				["show", `${since}:${packagePath}/package.json`],
				{ cwd: repositoryRoot },
			);
			return result.stdout;
		} catch {
			return undefined;
		}
	};
	const { stdout: changesetDiff } = await execFileAsync(
		"git",
		[
			"diff",
			"--name-status",
			"--find-renames",
			`${since}...HEAD`,
			"--",
			".changeset",
		],
		{ cwd: repositoryRoot },
	);

	try {
		await packageChangesetCoverage({
			root: repositoryRoot,
			changedFiles,
			readManifestFromBase,
			changesetDiffLines: changesetDiff.trim().split("\n").filter(Boolean),
		});
	} catch (error) {
		console.error(error.message);
		process.exitCode = 1;
	}
}

	return withCors(new Response(message, { status, headers }), origin);
}

function resolveHevyApiBaseUrl(value: string | undefined): string {
	if (value === undefined) return HEVY_API_BASE_URL;

	let url: URL;
	try {
		url = new URL(value);
	} catch {
		throw new TypeError("Invalid Hevy API base URL");
	}
	if (
		(url.protocol !== "http:" && url.protocol !== "https:") ||
		url.username ||
		url.password ||
		url.search ||
		url.hash ||
		url.pathname.replace(/\/+$/, "")
	) {
		throw new TypeError("Invalid Hevy API base URL");
	}
	return url.origin;
}

function createDefaultValidationClient(
	apiKey: string,
	baseUrl: string,
): HevyClient {
	return createHevyClient({
		apiKey,
		baseUrl,
		maxGetRetries: 0,
		timeoutMs: WORKER_VALIDATION_TIMEOUT_MS,
	});
}

function createDefaultRequestClient(
	apiKey: string,
	baseUrl: string,
	onLog: HevyClientFactoryContext["onLog"],
): HevyClient {
	return createHevyClient({ apiKey, baseUrl, onLog });
}

function createDefaultServer(
	createClient: CreateHevyMcpServerOptions["createClient"],
	lifecycleSignal?: AbortSignal,
	executionDeadline?: number,
	observer?: CreateHevyMcpServerOptions["observer"],
): McpServer {
	return createHevyMcpServer({
		createClient,
		observer,
		lifecycleSignal,
		executionDeadline,
	});
}

function createDefaultTransport(): WebStandardStreamableHTTPServerTransport {
	return new WebStandardStreamableHTTPServerTransport({
		sessionIdGenerator: undefined,
	});
}

function logWorkerFailure(
	context: string,
	error: Error | string,
	fields: Partial<WorkerRequestLogContext> = {},
): void {
	console.error({
		event: "worker.error",
		context,
		...fields,
		...createSafeErrorDiagnostic(error),
	});
}
function logOAuthResponse(
	context: WorkerRequestLogContext,
	status: number,
): void {
	if (status < 400) return;
	console.warn({
		event: "worker.oauth_response",
		...context,
		status,
	});
}

function executionHttpResponse(
	error: Error | string,
	message: string,
	status: number,
	origin: string | null,
): Response {
	return withCors(executionResponse(error, message, status), origin);
}

function resolveWorkerDependencies(
	dependencies: WorkerDependencies,
): ResolvedWorkerDependencies {
	return {
		createValidationClient:
			dependencies.createValidationClient ?? createDefaultValidationClient,
		createRequestClient:
			dependencies.createRequestClient ?? createDefaultRequestClient,
		createServer: dependencies.createServer ?? createDefaultServer,
		createTransport: dependencies.createTransport ?? createDefaultTransport,
		createObserver:
			dependencies.createObserver ??
			((options) => createWorkerToolObserver(options)),
	};
}

async function validateHevyApiKey(
	apiKey: string,
	hevyApiBaseUrl: string,
	createValidationClient: ResolvedWorkerDependencies["createValidationClient"],
	options?: HevyRequestOptions,
): Promise<HevyApiKeyValidation> {
	try {
		const validationDeadline = Math.min(
			options?.deadline ?? Number.POSITIVE_INFINITY,
			Date.now() + WORKER_VALIDATION_TIMEOUT_MS,
		);
		await createValidationClient(apiKey, hevyApiBaseUrl).getUserInfo({
			...options,
			deadline: validationDeadline,
		});
		return "valid";
	} catch (error) {
		if (options?.signal?.aborted) throw error;
		if (isHevyHttpError(error) && error.outcome === "deadline_exceeded") {
			throw error;
		}
		if (
			isHevyHttpError(error) &&
